11	const POINTER_RE = /^(?:\/(?:[^~/]|~[01])*)*$/;
12	const INDEX_RE = /^(?:0|[1-9][0-9]*)$/;
13	const OPS = ['add', 'remove', 'replace', 'move', 'copy', 'test'];
14	
15	function isValidPointer(pointer) {
16	  return typeof pointer === 'string' && POINTER_RE.test(pointer);
17	}
18	
19	function decodePointer(pointer) {
20	  if (pointer === '') return [];
21	  return pointer
22	    .slice(1)
23	    .split('/')
24	    .map((t) => t.replace(/~1/g, '/').replace(/~0/g, '~'));
25	}
