27	export function parsePointer(pointer) {
28	  if (typeof pointer !== 'string') throw new TypeError('pointer must be a string');
29	  if (!POINTER_RE.test(pointer)) throw new SyntaxError('invalid pointer');
30	  return decodePointer(pointer);
31	}
32	
33	function isObject(v) {
34	  return v !== null && typeof v === 'object' && !Array.isArray(v);
35	}
36	
37	function setMember(obj, name, value) {
38	  // defineProperty avoids the __proto__ setter and keeps an existing member's place.
39	  Object.defineProperty(obj, name, { value, writable: true, enumerable: true, configurable: true });
40	}
41	
42	// Iterative deep copy of a JSON value; keeps -0 and member order.
43	function deepCopy(value) {
44	  if (value === null || typeof value !== 'object') return value;
45	  const root = Array.isArray(value) ? [] : {};
46	  const stack = [[value, root]];
47	  while (stack.length) {
48	    const [src, dst] = stack.pop();
49	    if (Array.isArray(src)) {
50	      for (let k = 0; k < src.length; k++) {
51	        const v = src[k];
52	        if (v !== null && typeof v === 'object') {
53	          const c = Array.isArray(v) ? [] : {};
54	          dst.push(c);
55	          stack.push([v, c]);
56	        } else {
57	          dst.push(v);
58	        }
59	      }
60	    } else {
61	      for (const key of Object.keys(src)) {
62	        const v = src[key];
63	        if (v !== null && typeof v === 'object') {
64	          const c = Array.isArray(v) ? [] : {};
65	          setMember(dst, key, c);
66	          stack.push([v, c]);
67	        } else {
68	          setMember(dst, key, v);
69	        }
70	      }
71	    }
72	  }
73	  return root;
74	}
75	
76	function jsonType(v) {
77	  if (v === null) return 'null';
78	  if (Array.isArray(v)) return 'array';
79	  return typeof v;
80	}
81	
82	// Iterative JSON equality.
83	function deepEqual(a, b) {
84	  const stack = [[a, b]];
85	  while (stack.length) {
86	    const [x, y] = stack.pop();
87	    const t = jsonType(x);
88	    if (t !== jsonType(y)) return false;
89	    if (t === 'array') {
90	      if (x.length !== y.length) return false;
91	      for (let k = 0; k < x.length; k++) stack.push([x[k], y[k]]);
92	    } else if (t === 'object') {
93	      const kx = Object.keys(x);
94	      if (kx.length !== Object.keys(y).length) return false;
95	      for (const key of kx) {
96	        if (!Object.hasOwn(y, key)) return false;
97	        stack.push([x[key], y[key]]);
98	      }
99	    } else if (x !== y) {
100	      return false;
101	    }
102	  }
103	  return true;
104	}
