106	const NOT_FOUND = 1;
107	const BAD_INDEX = 2;
108	
109	// Returns the status of `token` on `node`: 0 if it names a value, else NOT_FOUND or BAD_INDEX.
110	function lookup(node, token) {
111	  if (Array.isArray(node)) {
112	    if (INDEX_RE.test(token)) return Number(token) < node.length ? 0 : NOT_FOUND;
113	    return token === '-' ? NOT_FOUND : BAD_INDEX;
114	  }
115	  if (node !== null && typeof node === 'object') return Object.hasOwn(node, token) ? 0 : NOT_FOUND;
116	  return NOT_FOUND;
117	}
118	
119	// Follows the first `n` tokens from `doc`, throwing on the first one that names nothing.
120	function walk(doc, tokens, n, notFound, index) {
121	  let node = doc;
122	  for (let k = 0; k < n; k++) {
123	    const token = tokens[k];
124	    const status = lookup(node, token);
125	    if (status === BAD_INDEX) throw new PatchError(`operation ${index}: bad index`, index);
126	    if (status === NOT_FOUND) throw new PatchError(`operation ${index}: ${notFound}`, index);
127	    node = Array.isArray(node) ? node[Number(token)] : node[token];
128	  }
129	  return node;
130	}
131	
132	function doAdd(doc, tokens, value, index) {
133	  if (tokens.length === 0) return value;
134	  const parent = walk(doc, tokens, tokens.length - 1, 'path not found', index);
135	  const last = tokens[tokens.length - 1];
136	  if (Array.isArray(parent)) {
137	    if (last === '-') {
138	      parent.push(value);
139	    } else if (INDEX_RE.test(last)) {
140	      const n = Number(last);
141	      if (n > parent.length) throw new PatchError(`operation ${index}: path not found`, index);
142	      parent.splice(n, 0, value);
143	    } else {
144	      throw new PatchError(`operation ${index}: bad index`, index);
145	    }
146	  } else if (isObject(parent)) {
147	    setMember(parent, last, value);
148	  } else {
149	    throw new PatchError(`operation ${index}: path not found`, index);
150	  }
151	  return doc;
152	}
153	
154	// Returns the value removed.
155	function doRemove(doc, tokens, notFound, index) {
156	  const parent = walk(doc, tokens, tokens.length - 1, notFound, index);
157	  const last = tokens[tokens.length - 1];
158	  walk(parent, [last], 1, notFound, index);
159	  if (Array.isArray(parent)) return parent.splice(Number(last), 1)[0];
160	  const value = parent[last];
161	  delete parent[last];
162	  return value;
163	}
164	
165	function doReplace(doc, tokens, value, index) {
166	  if (tokens.length === 0) return value;
167	  const parent = walk(doc, tokens, tokens.length - 1, 'path not found', index);
168	  const last = tokens[tokens.length - 1];
169	  walk(parent, [last], 1, 'path not found', index);
170	  if (Array.isArray(parent)) parent[Number(last)] = value;
171	  else setMember(parent, last, value);
172	  return doc;
173	}
174	
175	function isProperPrefix(a, b) {
176	  if (a.length >= b.length) return false;
177	  for (let k = 0; k < a.length; k++) if (a[k] !== b[k]) return false;
178	  return true;
179	}
180	
181	function checkOperation(op, i) {
182	  const fail = (reason) => new PatchError(`operation ${i}: ${reason}`, i);
183	  if (op === null || typeof op !== 'object' || Array.isArray(op)) throw fail('not an object');
184	  if (!Object.hasOwn(op, 'op') || !OPS.includes(op.op)) throw fail('bad op');
185	  const name = op.op;
186	  if (!Object.hasOwn(op, 'path') || !isValidPointer(op.path)) throw fail('bad path');
