188	  if (name === 'move' || name === 'copy') {
189	    if (!Object.hasOwn(op, 'from') || !isValidPointer(op.from)) throw fail('bad from');
190	    checked.from = decodePointer(op.from);
191	    checked.fromString = op.from;
192	  }
193	  if (name === 'add' || name === 'replace' || name === 'test') {
194	    if (!Object.hasOwn(op, 'value')) throw fail('missing value');
195	    checked.value = op.value;
196	  }
