204	export function applyPatch(doc, patch) {
205	  if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
206	  const ops = [];
207	  for (let i = 0; i < patch.length; i++) ops.push(checkOperation(patch[i], i));
208	
209	  let result = deepCopy(doc);
210	  for (let i = 0; i < ops.length; i++) {
211	    const op = ops[i];
212	    switch (op.op) {
213	      case 'add':
